import { motion, useInView } from "framer-motion";
import { useRef } from "react";
import { Github, ExternalLink } from "lucide-react";

const projects = [
  {
    title: "E-Commerce Platform",
    description: "Full-stack e-commerce app with React, Node.js, and MongoDB featuring user authentication, product management, and payment integration.",
    tech: ["React", "Node.js", "MongoDB", "Stripe"],
    github: "https://github.com",
    live: "https://demo.com"
  },
  {
    title: "Student Management System",
    description: "Desktop application for managing student records, attendance, and grades built with Java and MySQL.",
    tech: ["Java", "Swing", "MySQL"],
    github: "https://github.com",
    live: ""
  },
  {
    title: "Weather Dashboard",
    description: "Real-time weather application using OpenWeather API with location search and 7-day forecast display.",
    tech: ["React", "API", "CSS"],
    github: "https://github.com",
    live: "https://demo.com"
  },
  {
    title: "Task Management App",
    description: "Productivity app with drag-and-drop kanban boards, user authentication, and real-time updates.",
    tech: ["React", "Firebase", "Tailwind"],
    github: "https://github.com",
    live: "https://demo.com"
  }
];

const Projects = () => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true });

  return (
    <section id="projects" className="projects-section" ref={ref}>
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        animate={isInView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.6 }}
      >
        My Projects
      </motion.h2>

      <div className="projects-grid">
        {projects.map((project, index) => (
          <motion.div
            key={project.title}
            initial={{ opacity: 0, scale: 0.8 }}
            animate={isInView ? { opacity: 1, scale: 1 } : {}}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            whileHover={{ y: -10 }}
            className="project-card"
          >
            <div className="project-content">
              <h3>{project.title}</h3>
              <p>{project.description}</p>
              <div className="project-tech">
                {project.tech.map((t) => (
                  <span key={t} className="tech-tag">{t}</span>
                ))}
              </div>
              <div className="project-links">
                <a href={project.github} target="_blank" rel="noreferrer">
                  <Github size={20} /> Code
                </a>
                {project.live && (
                  <a href={project.live} target="_blank" rel="noreferrer">
                    <ExternalLink size={20} /> Demo
                  </a>
                )}
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </section>
  );
};

export default Projects;
